function BotBaseAIModifier.prototype.Init(self)
    if not self or self:IsNull() then
        return
    end
    local parent = self:GetParent()
    if not parent or parent:IsNull() then
        return
    end
    self.hero = parent
    local interval = IsInToolsMode() and self.ThinkIntervalTool or self.ThinkInterval
    self:SetThinkInterval(interval)
end
function BotBaseAIModifier.prototype.OnIntervalThink(self)
    self.hero = self:GetParent()
    if not self.hero or self.hero:IsNull() or not self.hero:IsAlive() then
        self:PauseThink()
        return
    end
    self:UpdateAdaptiveThinkInterval()
    self.gameTime = GameRules:GetDOTATime(false, false)
    if self.hero:HasModifier("modifier_mind_control") then
        return
    end
    if HeroUtil:NotActionable(self.hero) then
        local reason = self:GetIdleRecoveryBlockedReason("not_actionable")
        self:TryRecoverIdleBot(reason, reason == "muted")
        return
    end
    self:TryUpgradeAbilities()
    if not self.hero.isAbyssBot and not BotPushTiming:isAfterPhaseStart(self.gameTime) and not self:IsInPrePushOpeningActionWindow() and not self:ShouldUsePrePushTsAction() then
        self:LogPrePushDefenseSkip()
        self:BuildItem()
