    if not selectedEnhancement then
        return false
    end
    local oldItem = self.hero:GetItemInSlot(DOTA_ITEM_NEUTRAL_ACTIVE_SLOT)
    if oldItem then
        UTIL_RemoveImmediate(oldItem)
    end
    local oldEnhancement = self.hero:GetItemInSlot(DOTA_ITEM_NEUTRAL_PASSIVE_SLOT)
    if oldEnhancement then
        UTIL_RemoveImmediate(oldEnhancement)
    end
    self.hero:AddItemByName(selectedItem.name):SetLevel(selectedItem.level)
    self.hero:AddItemByName(selectedEnhancement.name):SetLevel(selectedEnhancement.level)
